import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Payment, Oficina, EstadoPago } from '../types';
import ConfirmationModal from './ConfirmationModal';

interface AccumulatedData {
    total: number;
    breakdown: { [key in Oficina]?: number };
}

interface AccumulatedReportProps {
    payments: Payment[];
    accumulatedData: AccumulatedData;
    setAccumulatedData: (update: React.SetStateAction<AccumulatedData>) => void;
}

const formatCurrency = (amount: number) => {
    return `Q ${amount.toLocaleString('es-GT', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
};

const AccumulatedReport: React.FC<AccumulatedReportProps> = ({ payments, accumulatedData, setAccumulatedData }) => {
    const [isConfirmOpen, setIsConfirmOpen] = useState(false);
    const [selectedOffices, setSelectedOffices] = useState<Oficina[]>(Object.values(Oficina));
    const [isOfficeDropdownOpen, setIsOfficeDropdownOpen] = useState(false);
    const [commissionRate, setCommissionRate] = useState(0.20); // Default 20%

    const officeFilterRef = useRef<HTMLDivElement>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const LOCAL_STORAGE_KEY = 'vokaAccumulatedReport';

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (officeFilterRef.current && !officeFilterRef.current.contains(event.target as Node)) {
                setIsOfficeDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, []);

    const currentPaidSummary = useMemo(() => {
        const paidPayments = payments.filter(p => p.estado === EstadoPago.Pagado);
        const total = paidPayments.reduce((sum, p) => sum + p.monto, 0);
        const breakdown = paidPayments.reduce((acc, p) => {
            if (!acc[p.oficina]) {
                acc[p.oficina] = 0;
            }
            acc[p.oficina]! += p.monto;
            return acc;
        }, {} as { [key in Oficina]?: number });
        return { total, breakdown };
    }, [payments]);

    const displayData = useMemo(() => {
        const breakdown: { [key in Oficina]?: number } = {};

        selectedOffices.forEach(oficina => {
            const currentAmount = currentPaidSummary.breakdown[oficina] || 0;
            const accumulatedAmount = Number(accumulatedData.breakdown?.[oficina]) || 0;
            if (currentAmount + accumulatedAmount > 0) {
                 breakdown[oficina] = currentAmount + accumulatedAmount;
            }
        });

        const total = Object.values(breakdown).reduce((sum, val) => sum + (Number(val) || 0), 0);

        return { total, breakdown };
    }, [currentPaidSummary, accumulatedData, selectedOffices]);

    const handleSave = () => {
        if (!(window as any).XLSX) {
            alert('La librería para exportar a Excel no está disponible.');
            return;
        }

        const dataToExport = [
            { Concepto: 'Total de Ganancias', Monto: displayData.total },
            ...Object.values(Oficina).map(oficina => ({
                Concepto: `Ganancia Oficina ${oficina}`,
                Monto: displayData.breakdown[oficina] || 0
            }))
        ];

        const worksheet = (window as any).XLSX.utils.json_to_sheet(dataToExport);
        const workbook = (window as any).XLSX.utils.book_new();
        (window as any).XLSX.utils.book_append_sheet(workbook, worksheet, 'Reporte de Ganancias');

        const today = new Date().toISOString().slice(0, 10);
        (window as any).XLSX.writeFile(workbook, `Reporte de Ganancias - ${today}.xlsx`);
    };

    const handleAccumulateClick = () => {
        fileInputRef.current?.click();
    };

    const handleFileImport = (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file || !(window as any).XLSX) return;

        event.target.value = ''; // Reset file input

        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const data = e.target?.result;
                const workbook = (window as any).XLSX.read(data, { type: 'binary' });
                const sheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[sheetName];
                const json: any[] = (window as any).XLSX.utils.sheet_to_json(worksheet);

                let importedTotal = 0;
                const importedBreakdown: { [key in Oficina]?: number } = {};

                json.forEach(row => {
                    const concepto = String(row['Concepto'] || '').trim();
                    const monto = parseFloat(String(row['Monto']));

                    if (isNaN(monto)) return;

                    if (concepto === 'Total Pagado' || concepto === 'Total de Ganancias') {
                         if (monto > importedTotal) importedTotal = monto;
                    } else if (concepto.startsWith('Oficina ') || concepto.startsWith('Ganancia Oficina ')) {
                        const oficinaKey = concepto.replace('Oficina ', '').replace('Ganancia ', '').trim() as Oficina;
                        if (Object.values(Oficina).includes(oficinaKey)) {
                            importedBreakdown[oficinaKey] = (importedBreakdown[oficinaKey] || 0) + monto;
                        }
                    }
                });

                const totalFromBreakdown = Object.values(importedBreakdown).reduce((sum, val) => sum + (Number(val) || 0), 0);
                if (importedTotal < totalFromBreakdown) {
                    importedTotal = totalFromBreakdown;
                }

                if (importedTotal === 0 && Object.keys(importedBreakdown).length === 0) {
                    alert('El archivo no parece tener el formato correcto. No se encontraron datos para acumular.');
                    return;
                }

                setAccumulatedData(prev => {
                    const newBreakdown: { [key in Oficina]?: number } = { ...prev.breakdown };
                     Object.values(Oficina).forEach(oficina => {
                        const oficinaKey = oficina as Oficina;
                        const prevAmount = Number(prev.breakdown[oficinaKey]) || 0;
                        const importedAmount = importedBreakdown[oficinaKey] || 0;
                        newBreakdown[oficinaKey] = prevAmount + importedAmount;
                    });

                    const newTotal = Object.values(newBreakdown).reduce((sum, val) => sum + (Number(val) || 0), 0);

                    return { total: newTotal, breakdown: newBreakdown };
                });

                alert('Datos acumulados correctamente.');

            } catch (error) {
                console.error('Error al procesar el archivo acumulado:', error);
                alert('Ocurrió un error al procesar el archivo. Asegúrese de que sea un archivo de acumulado válido.');
            }
        };
        reader.readAsBinaryString(file);
    };

    const handleConfirmDelete = () => {
        setAccumulatedData({ total: 0, breakdown: {} });
        localStorage.removeItem(LOCAL_STORAGE_KEY);
        setIsConfirmOpen(false);
    };

    const handleOfficeChange = (oficina: Oficina) => {
        setSelectedOffices(prev => {
            const newOficinas = prev.includes(oficina)
                ? prev.filter(o => o !== oficina)
                : [...prev, oficina];
            return newOficinas;
        });
    };

    const handleSelectAllOffices = () => {
        setSelectedOffices(Object.values(Oficina));
    };

    const handleClearAllOffices = () => {
        setSelectedOffices([]);
    };

    const getOfficeButtonText = () => {
        const totalOffices = Object.values(Oficina).length;
        const selectedCount = selectedOffices.length;

        if (selectedCount === totalOffices) return 'Oficinas (Todas)';
        if (selectedCount === 0) return 'Oficinas (Ninguna)';
        if (selectedCount === 1) return `Oficina ${selectedOffices[0]}`;
        return `Oficinas (${selectedCount}/${totalOffices})`;
    };

    return (
        <>
            <div className="bg-white p-6 rounded-lg shadow-md mb-8">
                <input
                    type="file"
                    ref={fileInputRef}
                    onChange={handleFileImport}
                    className="hidden"
                    accept=".xlsx, .xls"
                />
                <div className="flex flex-wrap gap-4 justify-between items-center mb-4">
                    <h2 className="text-xl font-bold text-voka-blue">Reporte Ganancias Mensual</h2>
                    <div className="relative" ref={officeFilterRef}>
                        <button
                            type="button"
                            onClick={() => setIsOfficeDropdownOpen(!isOfficeDropdownOpen)}
                            className="px-4 py-2 bg-white text-left border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-offset-1 focus:ring-voka-blue transition flex items-center justify-between min-w-[180px]"
                        >
                            <span>{getOfficeButtonText()}</span>
                            <svg className={`h-5 w-5 text-gray-400 transform transition-transform ${isOfficeDropdownOpen ? 'rotate-180' : ''}`} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
                        </button>
                        {isOfficeDropdownOpen && (
                            <div className="absolute z-10 mt-1 w-full bg-white border border-gray-300 rounded-md shadow-lg">
                                <div className="p-2 space-y-2">
                                    {Object.values(Oficina).map(o => (
                                        <label key={o} className="flex items-center space-x-3 px-2 py-1 hover:bg-gray-100 rounded-md cursor-pointer">
                                            <input
                                                type="checkbox"
                                                checked={selectedOffices.includes(o)}
                                                onChange={() => handleOfficeChange(o)}
                                                className="h-4 w-4 rounded border-gray-300 text-voka-blue focus:ring-voka-blue"
                                            />
                                            <span className="text-sm text-gray-700">{o}</span>
                                        </label>
                                    ))}
                                </div>
                                <div className="flex justify-between p-2 border-t border-gray-200">
                                    <button onClick={handleSelectAllOffices} className="text-sm text-voka-blue hover:underline">Todas</button>
                                    <button onClick={handleClearAllOffices} className="text-sm text-voka-red hover:underline">Limpiar</button>
                                </div>
                            </div>
                        )}
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    <div className="bg-gradient-to-r from-voka-blue to-gray-800 text-white p-6 rounded-lg shadow-lg text-center">
                        <p className="text-lg font-medium opacity-80">Total General Acumulado</p>
                        <p className="text-4xl font-extrabold tracking-tight mt-2 font-mono">{formatCurrency(displayData.total)}</p>
                    </div>
                    <div className="bg-gradient-to-r from-voka-green to-teal-600 text-white p-6 rounded-lg shadow-lg text-center flex flex-col items-center justify-between">
                        <div>
                            <p className="text-lg font-medium opacity-80">Total comisión por servicio</p>
                            <p className="text-4xl font-extrabold tracking-tight mt-2 font-mono">{formatCurrency(displayData.total * commissionRate)}</p>
                        </div>
                        <div className="mt-4 bg-black bg-opacity-20 p-1 rounded-lg flex items-center">
                            <button 
                                onClick={() => setCommissionRate(0.15)}
                                className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${commissionRate === 0.15 ? 'bg-white text-teal-600 shadow-sm' : 'text-white hover:bg-white hover:bg-opacity-10'}`}
                            >
                                15%
                            </button>
                            <button 
                                onClick={() => setCommissionRate(0.20)}
                                className={`px-3 py-1 text-xs font-bold rounded-md transition-all ${commissionRate === 0.20 ? 'bg-white text-teal-600 shadow-sm' : 'text-white hover:bg-white hover:bg-opacity-10'}`}
                            >
                                20%
                            </button>
                        </div>
                    </div>
                    <div className="md:col-span-2 lg:col-span-1">
                        <h3 className="text-lg font-semibold text-gray-700 mb-3">Desglose por Oficina</h3>
                        <div className="space-y-2 max-h-48 overflow-y-auto pr-2">
                           {Object.keys(displayData.breakdown).length > 0 ? (
                                Object.entries(displayData.breakdown).map(([oficina, amount]) => (
                                    <div key={oficina} className="flex justify-between items-center bg-gray-100 p-3 rounded-md">
                                        <span className="font-medium text-gray-800">Oficina {oficina}</span>
                                        <span className="font-semibold text-gray-800 font-mono">{formatCurrency(Number(amount) || 0)}</span>
                                    </div>
                                ))
                           ) : (
                                <div className="text-center py-6 bg-gray-100 rounded-md">
                                    <p className="text-gray-500">No hay datos para las oficinas seleccionadas.</p>
                                </div>
                           )}
                        </div>
                    </div>
                </div>
            </div>
            {isConfirmOpen && (
                <ConfirmationModal
                    isOpen={isConfirmOpen}
                    onClose={() => setIsConfirmOpen(false)}
                    onConfirm={handleConfirmDelete}
                    title="Confirmar Eliminación de Acumulado"
                    message="¿Estás seguro de que deseas eliminar todos los datos acumulados? Esta acción restablecerá el reporte de ganancias a cero y no se puede deshacer."
                />
            )}
        </>
    );
};

export default AccumulatedReport;
